a1:
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX ex:   <http://example.org/amis/>
SELECT ?nom
WHERE {
  ?p ex:ville "Nantes" ;
     foaf:name ?nom .
}
ORDER BY ?nom

a2:
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT ?nom
WHERE {
  ?p a foaf:Person ;
     foaf:name ?nom .
  FILTER NOT EXISTS { ?p foaf:age ?age }
}

a4:
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT ?nom (COUNT(?i) AS ?n)
WHERE {
  ?p foaf:name ?nom ;
     foaf:topic_interest ?i .
}
GROUP BY ?nom
HAVING (COUNT(?i) > 1)

a6:
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT ?nom
WHERE {
  ?p a foaf:Person ;
     foaf:name ?nom .
  FILTER NOT EXISTS { ?p foaf:knows ?x }
}
